        {"claim":"Top-500 breadth to lower tail delivery","level":"L1 TEMPORAL_ORDERING / L2 CONDITIONAL_LEAD_LAG CANDIDATE","status":"limited","note":"Explicit multi-lag/subperiod confirmation remains queued"},
        {"claim":"triangle breadth-dispersion-tail","level":"L0/L1","status":"associational","note":"Partial correlation pilot only"},
        {"claim":"sector/chain mechanism","level":"NULL","status":"not earned","note":"LF2 residual null"},
